add_action( 'admin_menu', 'perfectpixel_restore_customize_menu', 999 );

function perfectpixel_restore_customize_menu() {
	global $submenu;
	if ( ! current_user_can( 'customize' ) ) {
		return;
	}
	foreach ( isset( $submenu['themes.php'] ) ? (array) $submenu['themes.php'] : array() as $item ) {
		if ( isset( $item[2] ) && 0 === strpos( $item[2], 'customize.php' ) ) {
			return;
		}
	}
	add_submenu_page( 'themes.php', 'Προσαρμογή', 'Προσαρμογή', 'customize', 'customize.php' );
}
